const lens = document.getElementById('ai4a11y-magnifier');
const isEnabled = !!lens;
if (!isEnabled) {
  return lens === null;
}

if (lens.getAttribute('aria-hidden') !== 'true') return false;
const cs = window.getComputedStyle(lens);
if (cs.pointerEvents !== 'none') return false;
if (cs.position !== 'fixed') return false;
if (cs.boxSizing !== 'border-box') return false;

function getLuminance(rgbStr) {
  const m = rgbStr.match(/\d+/g);
  if (!m) return 0;
  const [r, g, b] = m.slice(0, 3).map(v => {
    const c = Number(v) / 255;
    return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
function contrast(c1, c2) {
  const l1 = getLuminance(c1);
  const l2 = getLuminance(c2);
  return (Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05);
}
const ratio = contrast(cs.color, cs.backgroundColor);
return ratio >= 4.5;

