const lens = document.getElementById('ai4a11y-magnifier');
const disc = document.getElementById('disclaimer');
const subBtn = document.getElementById('sub-btn');
if (!disc || !subBtn) return false;
if (!lens) return true;

const dRect = disc.getBoundingClientRect();
const px = Math.round(dRect.left + 40);
const py = Math.round(dRect.top + 12);

document.dispatchEvent(new MouseEvent('mousemove', { bubbles: true, clientX: px, clientY: py }));
await new Promise(r => requestAnimationFrame(() => setTimeout(r, 60)));

const lRect = lens.getBoundingClientRect();
const coversX = px >= lRect.left && px <= lRect.right;
const coversY = py >= lRect.top && py <= lRect.bottom;
if (coversX && coversY) return false;

// Focus onto button -> lens hides so focused element is never obscured
subBtn.focus();
if (window.getComputedStyle(lens).display !== 'none') return false;

subBtn.blur();
document.dispatchEvent(new MouseEvent('mouseleave'));
return true;

